import{bV as s,aL as i,u as e,G as r}from"./chunks/framework.DxlKcdLe.js";const k=JSON.parse('{"title":"抓包破解wifi","description":"","frontmatter":{"title":"抓包破解wifi","date":"2023-11-16T15:02:41.000Z","permalink":"/pages/93a22b/","categories":["更多","实用技巧"],"tags":[null]},"headers":[],"relativePath":"pages/93a22b.md","filePath":"更多/实用技巧/05.抓包破解wifi.md","lastUpdated":1785135823000}'),t={name:"pages/93a22b.md"};function n(p,a,l,c,o,h){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="通过aircrack-ng等工具获取wifi密码" tabindex="-1">通过Aircrack-ng等工具获取Wifi密码- <a class="header-anchor" href="#通过aircrack-ng等工具获取wifi密码" aria-label="Permalink to &quot;通过Aircrack-ng等工具获取Wifi密码-&quot;">​</a></h1><p>在MacOS上，利用Aircrack-ng等工具通过跑字典方式获取附近可见wifi的明文密码</p><h1 id="本文仅供学习交流-破解他人wifi可能要负担法律责任-请勿触犯法律。本文演示使用的是作者本人的wifi。" tabindex="-1">本文仅供学习交流，破解他人wifi可能要负担法律责任，请勿触犯法律。本文演示使用的是作者本人的wifi。 <a class="header-anchor" href="#本文仅供学习交流-破解他人wifi可能要负担法律责任-请勿触犯法律。本文演示使用的是作者本人的wifi。" aria-label="Permalink to &quot;本文仅供学习交流，破解他人wifi可能要负担法律责任，请勿触犯法律。本文演示使用的是作者本人的wifi。&quot;">​</a></h1><h3 id="主要思路" tabindex="-1">主要思路 <a class="header-anchor" href="#主要思路" aria-label="Permalink to &quot;主要思路&quot;">​</a></h3><p>用户与路由器建立连接是通过含有hash加密的密码握手包来确认身份的。那么如果得到握手包，获取到密码的hash值。那么通过跑字典比对hash值就可以得出密码的明文。</p><p>所需工具：</p><ul><li>一个可用的支持监听功能的无线网卡（这句基本是废话）</li><li>Terminal（MacOS系统自带，新版名为‘终端‘）</li><li>Airport工具（MacOS系统自带）</li><li>Aircrack-ng（破解工具）</li><li>一个密码字典（项目中提供了两个，也可以用其他的替代）</li><li>PS:你或许还需要HomeBrew（用于安装Aircrack-ng）</li></ul><h2 id="预备" tabindex="-1">预备！ <a class="header-anchor" href="#预备" aria-label="Permalink to &quot;预备！&quot;">​</a></h2><p>1.安装HomeBrew</p><p>打开终端Terminal，输入如下命令，自动安装HomeBrew。安装完毕后可输入 <code>brew --version</code> 检测，若提示 <code>Homebrew 1.6.3</code> 则表明安装正确。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/usr/bin/ruby</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/Homebrew/install/master/install)&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>2.安装Aircrack-ng</p><p>第一步完成后，在终端中输入如下命令，进行安装。安装完毕后可输入 <code>aircrack-ng</code> 检测，若提示一系列关于Aircrack-ng的版本信息以及命令选项，则表明安装正确。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aircrack-ng</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>3.下载密码字典</p><p>作者所用的密码字典是网上的前辈帖子发到帖子里的，当然可以用其他字典替换。</p><p><a href="http://pan.baidu.com/s/1o7MCcHk" target="_blank" rel="noreferrer">精简版字典 约700M</a></p><p><a href="http://pan.baidu.com/s/1clxaCA" target="_blank" rel="noreferrer">完善版字典 约15G</a></p><h2 id="开始" tabindex="-1">开始！ <a class="header-anchor" href="#开始" aria-label="Permalink to &quot;开始！&quot;">​</a></h2><p>1.查看本机网卡信息。</p><p>点屏幕左上角点小苹果-&gt;关于本机-&gt;系统报告，找到图中所示，Wi-Fi网卡，记住网卡的BSD设备名称，也就是<code>en0</code> <code>en1</code>之类的那些。</p><p><img src="https://raw.githubusercontent.com/ZoraZora59/Get_Wifi_Password_On_MacOS/master/Screenshots/S1.png" alt="截图1"></p><p>2.启动终端，输入下列命令，探测周围的Wi-Fi信号。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /System/Library/PrivateFrameworks/Apple80211.framework/Versions/Current/Resources/airport</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="https://raw.githubusercontent.com/ZoraZora59/Get_Wifi_Password_On_MacOS/master/Screenshots/S2.png" alt="截图2"></p><p>图中<code>SSID</code>为Wifi名称，<code>BSSID</code>为路由器的MAC地址，<code>RSSI</code>为信号强度（这个怎么算的···好像要弄懂信噪比的概念，与破解无关，暂时不管，可以通过点屏幕右上角的Wi-Fi标志看信号强弱嘛🤪），<code>CHANNEL</code>是该Wi-Fi所用信道，<code>SECURITY</code>是该Wi-Fi的加密方式（现在主流加密方式是WPA2，所以我们针对WPA2进行破解）。</p><p>3.在终端中输入下列命令，监听路由器信道，等待获取握手包</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /System/Library/PrivateFrameworks/Apple80211.framework/Versions/Current/Resources/airport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> en0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sniff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="https://raw.githubusercontent.com/ZoraZora59/Get_Wifi_Password_On_MacOS/master/Screenshots/S3.png" alt="截图3"></p><p>尽可能选在用户大批连接前开始监听，不然可能会耗费漫长的时间监听到一大堆没用的数据。（这一步可以通过欺骗包方法使用户端误以为路由器重启，从而快速获得握手包。具体方法作者正在研究大佬的博客）</p><p>使用ctrl+c停止监听，系统会将监听到的数据cap文件保存到本地/tmp文件夹下。打开cap文件，查看cap文件中的数据是否被抓取到，输入命令查看：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo aircrack-ng /tmp/airportSniffhKI8Kg.cap</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>4.等了很久！看看监听的怎么样了！<code>CTRL+C</code>快捷键中断监听，在终端里输入<code>cd /tmp</code>进入tmp目录，输入<code>ls</code>显示目录内文件，监听到的包就放在这里，文件名为<code>airportSniffCrRc8p.cap</code>（就是下图中框起来的那个）😈</p><p><img src="https://raw.githubusercontent.com/ZoraZora59/Get_Wifi_Password_On_MacOS/master/Screenshots/S4.png" alt="截图4"></p><p>在终端中输入命令对监听包进行分析，看看里面有没有握手包（作者的包是airportSniffCrRc8p.cap，密码字典放在了&#39;密码破解字典&#39;文件夹里，需要自行更改为自己监听到的包名和字典）</p><div class="language-sheel vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sheel</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo aircrack-ng -w ~/密码破解字典/crackstation-human-only.txt /tmp/airportSniffCrRc8p.cap</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="https://raw.githubusercontent.com/ZoraZora59/Get_Wifi_Password_On_MacOS/master/Screenshots/S5.png" alt="截图5"></p><p>如果监听包的内容太多可以用快捷键<code>Command+F</code>查找关键字来看。</p><p>握手包的标记为<code>1 handshake</code>，除此之外的都是无效信息。如果全部内容都没有<code>1 handshake</code>，很遗憾，重新回到第三步，继续监听信道-&gt;分析-&gt;监听信道-&gt;分析，直到分析到有握手包标记的监听包。</p><p>5.当发现有握手包之后，接下来就是最激(man)动(de)人(yao)心(si)的破解阶段！在 aircrack-ng 程序中看到下图提示后输入握手包所在行数（就是#对应的那一列）</p><p><img src="https://raw.githubusercontent.com/ZoraZora59/Get_Wifi_Password_On_MacOS/master/Screenshots/S6.png" alt="截图6"></p><p>或者在终端中输入下列命令，开始对监听包进行密码破解（Hash值比对)。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aircrack-ng</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/密码破解字典/crackstation-human-only.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 50:3A:A0:D2:8C:AE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/airportSniffCrRc8p.cap</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="https://raw.githubusercontent.com/ZoraZora59/Get_Wifi_Password_On_MacOS/master/Screenshots/S7.png" alt="截图7"></p><p>这一步默认是由CPU完成的，而CPU本身相对而言不擅长做这种单一的hash计算，擅长做这个的是GPU（原理同显卡挖矿）。可以通过工具将这一步交由GPU来完成，效率会高很多。（Elcomsoft Wireless Security Auditor简称EWSA，一个密码破解工具，支持显卡，N卡为主，而且还支持多核运算）</p><p>6.Finally！密码Hash比对完毕/比对失败！</p><p>失败原因非常简单：字典不给力，换个更大更全的吧。或者是设密码的人太变态，弄个<code>LN&amp;tDIr82!1B</code>之类的复杂密码，如果是这样的话，放弃吧🤣不然破解到天荒地老。</p><p>如果比对成功，程序会进入如下界面，<code>KEY FOUND ![*]</code>里面的‘*’就是密码.恭喜获得成功🎉</p><p><img src="https://raw.githubusercontent.com/ZoraZora59/Get_Wifi_Password_On_MacOS/master/Screenshots/S8.png" alt="截图8"> 参考：</p><p><a href="https://www.cnblogs.com/hzxll/p/16271446.html" target="_blank" rel="noreferrer">MAC系统下破解WIFI密码（亲测可用，含wifi密码字典） - HZX↑ - 博客园</a></p><p><a href="https://github.com/ZoraZora59/Get_Wifi_Password_On_MacOS" target="_blank" rel="noreferrer">GitHub - ZoraZora59/Get_Wifi_Password_On_MacOS: 在MacOS上，利用Aircrack-ng等工具获取附近可见wifi的明文密码</a></p><p><a href="https://github.com/conwnet/wpa-dictionary" target="_blank" rel="noreferrer">WPA/WPA2 密码字典，用于 wifi 密码暴力破解</a></p>',52)])])}const g=s(t,[["render",n]]);export{k as __pageData,g as default};
